content:
En un videojuego, un personaje está en el punto $P(3, -2)$ del plano cartesiano. Se le aplican, en este orden, las siguientes transformaciones:
1) una reflexión respecto de la recta $y = x$;
2) una traslación según el vector $(-4, 1)$;
3) una rotación de $180^\circ$ con centro en el origen.

¿Cuáles son las coordenadas finales del personaje?

verify:
const A=[2,3],Ap=[-1,-3],B=[4,1],Bp=[-5,1],Q=[0,4];
const k=(Bp[0]-Ap[0])/(B[0]-A[0]); const k2=(Bp[1]-Ap[1])/(B[1]-A[1]); if(Math.abs(k-k2)>1e-9) return null;
const C=[(Ap[0]-k*A[0])/(1-k),(Ap[1]-k*A[1])/(1-k)];
const H=(P)=>[C[0]+k*(P[0]-C[0]),C[1]+k*(P[1]-C[1])];
const eq=(u,v)=>Math.abs(u[0]-v[0])<1e-9&&Math.abs(u[1]-v[1])<1e-9;
if(!eq(H(B),Bp)) return null;
const o={A:[-1,7],B:[0,-8],C:[1.5,-0.5],D:[3,-5]};
const ok=Object.keys(o).filter(l=>eq(o[l],H(Q))); return ok.length===1?ok[0]:null;

const k=-3; const L=(x)=>2*x+3; const pts=[0,1,2].map(x=>[k*x,k*L(x)]);
const o={A:(X)=>2*X+3*k,B:(X)=>2*k*X+3,C:(X)=>2*k*X+3*k,D:(X)=>2*X+3/k};
const ok=Object.keys(o).filter(l=>pts.every(p=>Math.abs(o[l](p[0])-p[1])<1e-9)); return ok.length===1?ok[0]:null;

const O=[1,2]; const H=(k)=>(P)=>[O[0]+k*(P[0]-O[0]),O[1]+k*(P[1]-O[1])];
const P=[4,-3],A=[2,5],B=[-1,0];
const Pp=H(-1)(P); const I=Math.abs((P[0]+Pp[0])/2-O[0])<1e-9&&Math.abs((P[1]+Pp[1])/2-O[1])<1e-9;
const k=-2; const Ap=H(k)(A),Bp=H(k)(B); const u=[B[0]-A[0],B[1]-A[1]],v=[Bp[0]-Ap[0],Bp[1]-Ap[1]];
const II=Math.abs(u[0]*v[1]-u[1]*v[0])<1e-9;
const len=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]); const III=Math.abs(len(Ap,Bp)-k*len(A,B))<1e-9;
if(I&&II&&!III) return 'D'; return null;

const P=[1,2],Pp=[7,8],k=3; const C=[(Pp[0]-k*P[0])/(1-k),(Pp[1]-k*P[1])/(1-k)];
if(Math.abs(C[0]+k*(P[0]-C[0])-Pp[0])>1e-9) return null; const d=Math.hypot(Pp[0]-C[0],Pp[1]-C[1]);
const s=Math.SQRT2; const o={A:3*s,B:9*s/2,C:6*s,D:9*s}; const ok=Object.keys(o).filter(l=>Math.abs(o[l]-d)<1e-9); return ok.length===1?ok[0]:null;

const A=[0,0],B=[8,2],C=[3,7]; const mid=(u,v)=>[(u[0]+v[0])/2,(u[1]+v[1])/2];
const M=mid(B,C),N=mid(C,A),P=mid(A,B); const G=[(A[0]+B[0]+C[0])/3,(A[1]+B[1]+C[1])/3];
const H=(c,k)=>(p)=>[c[0]+k*(p[0]-c[0]),c[1]+k*(p[1]-c[1])]; const eq=(a,b)=>Math.abs(a[0]-b[0])<1e-9&&Math.abs(a[1]-b[1])<1e-9;
const o={A:H(A,0.5),B:H(G,-0.5),C:H(G,0.5),D:H(M,-0.5)};
const ok=Object.keys(o).filter(l=>eq(o[l](A),M)&&eq(o[l](B),N)&&eq(o[l](C),P)); return ok.length===1?ok[0]:null;

const C=[1,2],P=[3,6],Q=[5,0]; const k=-C[1]/(P[1]-C[1]); const Qp=[C[0]+k*(Q[0]-C[0]),C[1]+k*(Q[1]-C[1])];
const eq=(a,b)=>Math.abs(a[0]-b[0])<1e-9&&Math.abs(a[1]-b[1])<1e-9;
const o={A:[-7,6],B:[-2.5,0],C:[-1,3],D:[3,1]}; const ok=Object.keys(o).filter(l=>eq(o[l],Qp)); return ok.length===1?ok[0]:null;

const dV=0.6; const r1=1.7; const r2=r1*Math.pow(10,dV/3); const V=(r)=>4/3*Math.PI*r**3, A=(r)=>4*Math.PI*r*r;
if(Math.abs(Math.log10(V(r2))-Math.log10(V(r1))-dV)>1e-9) return null; const dA=Math.log10(A(r2))-Math.log10(A(r1));
const o={A:0.2,B:0.3,C:0.36,D:0.4}; const ok=Object.keys(o).filter(l=>Math.abs(o[l]-dA)<1e-9); return ok.length===1?ok[0]:null;

const h=30,a=35*Math.PI/180,b=58*Math.PI/180; const AB=h/Math.tan(a)+h/Math.tan(b);
const o={A:h*(1/Math.tan(a)+1/Math.tan(b)),B:h*(Math.tan(a)+Math.tan(b)),C:h/(Math.tan(a)+Math.tan(b)),D:h*(1/Math.sin(a)+1/Math.sin(b))};
const ok=Object.keys(o).filter(l=>Math.abs(o[l]-AB)<1e-9); return ok.length===1?ok[0]:null;

const r1=(84/4-9)/6;
const r2=3; const ok2=Math.abs(4*Math.PI*r2*r2-4/3*Math.PI*r2**3)<1e-9;
const g=(r)=>4*Math.PI*r*r-4/3*Math.PI*r**3; let roots=0; for(let r=0.5;r<50;r+=0.5){ if(g(r)===0||g(r)*g(r+0.5)<0) roots++; }
const lin1=Math.abs(4*Math.PI*((r1+3)**2-r1*r1)-84*Math.PI)<1e-9; const lin1b=Math.abs(4*Math.PI*((r1+1+3)**2-(r1+1)**2)-84*Math.PI)>1e-6;
if(lin1&&lin1b&&ok2&&roots===1) return 'D'; return null;

const tri=(s)=>({a:12*s,b:5*s,c:13*s}); const t1=tri(1),t2=tri(2);
const c1=Math.abs(t1.b/t1.c-5/13)<1e-9&&Math.abs(t2.b/t2.c-5/13)<1e-9; const ar1=t1.a*t1.b/2, ar2=t2.a*t2.b/2; const insuf1=c1&&Math.abs(ar1-ar2)>1e-9;
const c=26,p=60/169; const S=Math.sin, C=Math.cos; const angs=[]; for(let t=0.001;t<Math.PI/2;t+=0.0005){ if(Math.abs(S(t)*C(t)-p)<2e-4) angs.push(t);}
if(angs.length===0) return null; const areas=angs.map(t=>(c*S(t))*(c*C(t))/2); const suf2=areas.every(x=>Math.abs(x-120)<0.1)&&Math.abs(0.5*c*c*p-120)<1e-9;
const t2ok=Math.abs(t2.c-26)<1e-9&&Math.abs((t2.a/t2.c)*(t2.b/t2.c)-p)<1e-9;
if(insuf1&&suf2&&t2ok) return 'B'; return null;
